class TextTools {

  // a) zählt die Großbuchstaben A-Z in text
  public int zaehleGrossbuchstaben(String text) {
    int anzahl = 0;
    for (int i = 0; i < text.length(); i++) {
      char c = text.charAt(i);
      if (c >= 'A' && c <= 'Z') {
        anzahl++;
      }
    }
    return anzahl;
  }

  // b) liefert den größten Wert eines int-Arrays
  public int groesster(int[] werte) {
    int max = werte[0];
    for (int i = 1; i < werte.length; i++) {
      if (werte[i] > max) {
        max = werte[i];
      }
    }
    return max;
  }

  public static void main(String[] s) {
    TextTools t = new TextTools();
    System.out.println(t.zaehleGrossbuchstaben("Hallo Welt"));
    System.out.println(t.zaehleGrossbuchstaben("OFP Klausur 2026"));
    int[] zahlen = { 4, -2, 17, 9 };
    System.out.println(t.groesster(zahlen));
  }
}

