class Summenmatrix {
  public static void main(String[] str) {
    int n = 4;
    int[][] m = new int[n][n];

    // erste Zeile und erste Spalte: 1, 2, ..., n
    for (int i = 0; i < n; i++) {
      m[i][0] = i + 1;
      m[0][i] = i + 1;
    }

    // jede weitere Zelle: oben + links
    for (int i = 1; i < n; i++) {
      for (int j = 1; j < n; j++) {
        m[i][j] = m[i - 1][j] + m[i][j - 1];
      }
    }

    // zeilenweise ausgeben
    for (int i = 0; i < n; i++) {
      String zeile = "";
      for (int j = 0; j < n; j++) {
        zeile = zeile + m[i][j];
        if (j < n - 1) {
          zeile = zeile + ",";
        }
      }
      System.out.println(zeile);
    }
  }
}

