class WordleHinweis {
  public static void main(String[] str) {
    String loesung = "weary";
    String[] versuche = { "wharf", "wears", "weary" };
    String hint = "-----";

    for (int v = 0; v < versuche.length; v++) {
      String in = versuche[v];
      char[] hintChar = hint.toCharArray();
      if (in.length() >= loesung.length()) {
        for (int i = 0; i < loesung.length(); i++) {
          if ( in.charAt(i) == loesung.charAt(i) ) {
            hintChar[i] = in.charAt(i);
          } else {
            hintChar[i] = '-';
          }
        }
      }
      hint = new String(hintChar);
      System.out.println(in + " -> " + hint);
