exercises.solution:
class Histogramm {
  public static void main(String[] str) {
    int[] liste = { 3, 1, 4, 2, 5 };
    int hoehe = 5;

    // 1. 2D-Array von booleans füllen:
    boolean[][] hist = new boolean[hoehe][liste.length];
    for (int zeile = 0; zeile < hoehe; zeile++) {
      for (int spalte = 0; spalte < liste.length; spalte++) {
        if (liste[spalte] > zeile) {
          hist[zeile][spalte] = true;
        } else {
          hist[zeile][spalte] = false;
        }
      }
    }

    // 2. Histogramm von oben nach unten zeichnen:
    for (int zeile = hoehe - 1; zeile >= 0; zeile--) {
      for (int spalte = 0; spalte < liste.length; spalte++) {
        if (hist[zeile][spalte] == true) {
          System.out.print("#");
        } else {
          System.out.print(" ");
        }
      }
      System.out.println();
    }
  }
}

