class RunLength {

  // liefert die RLE-Kodierung von input, z.B. "aaabbbcc" -> "a3b3c2"
  public static String kodiere(String input) {
    String ergebnis = "";
    int i = 0;
    while (i < input.length()) {
      char c = input.charAt(i);
      int anzahl = 0;
      while (i < input.length() && input.charAt(i) == c) {
        anzahl++;
        i++;
      }
      ergebnis = ergebnis + c + anzahl;
    }
    return ergebnis;
  }

  public static void main(String[] s) {
    System.out.println("Komprimiert: " + kodiere("aaabbbcc"));
    System.out.println("Komprimiert: " + kodiere("xyz"));
    System.out.println("Komprimiert: " + kodiere("aabbaa"));
  }
}
